// Fechas ISO estrictas, interpretadas en UTC para evitar cambios por zona horaria.
function fechaUTC(iso) {
  if (typeof iso !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(iso)) {
    throw new Error(`Fecha ISO inválida: ${String(iso)}`);
  }
  const [ano, mes, dia] = iso.split('-').map(Number);
  const fecha = new Date(Date.UTC(ano, mes - 1, dia));
  if (fecha.getUTCFullYear() !== ano || fecha.getUTCMonth() !== mes - 1 || fecha.getUTCDate() !== dia) {
    throw new Error(`Fecha imposible: ${iso}`);
  }
  return fecha;
}
function formatoISO(fecha) { return fecha.toISOString().slice(0, 10); }
function sumarDiasISO(iso, cantidad) {
  const f = fechaUTC(iso);
  f.setUTCDate(f.getUTCDate() + cantidad);
  return formatoISO(f);
}
function hoyCostaRica(ahora = new Date()) {
  const partes = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Costa_Rica', year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(ahora);
  const valor = (tipo) => partes.find(p => p.type === tipo)?.value;
  return `${valor('year')}-${valor('month')}-${valor('day')}`;
}



/** Solo feriados nacionales públicos. Feriados regionales no aplican a todas las facturas. */
class CalendarioLaboral {
  #feriados;
  #aniosDisponibles;

  constructor(registros = [], aniosDisponibles = []) {
    if (!Array.isArray(registros)) throw new Error('La API de feriados debe devolver un arreglo');
    this.#feriados = new Set();
    this.#aniosDisponibles = new Set(aniosDisponibles.map(Number));
    for (const feriado of registros) {
      if (typeof feriado !== 'object' || feriado === null) throw new Error('Feriado inválido');
      if (feriado.countryCode && feriado.countryCode !== 'CR') {
        throw new Error(`El feriado pertenece a otro país: ${feriado.countryCode}`);
      }
      fechaUTC(feriado.date);
      if (feriado.global === true && (!Array.isArray(feriado.types) || feriado.types.includes('Public'))) {
        this.#feriados.add(feriado.date);
      }
    }
  }

  esDiaHabil(fechaISO) {
    const fecha = fechaUTC(fechaISO);
    const anio = fecha.getUTCFullYear();
    if (!this.#aniosDisponibles.has(anio)) throw new Error(`Sin calendario de feriados verificado para ${anio}`);
    const dia = fecha.getUTCDay();
    return dia !== 0 && dia !== 6 && !this.#feriados.has(fechaISO);
  }

  sumarDiasHabiles(fechaEmision, dias = 15) {
    fechaUTC(fechaEmision);
    if (!Number.isInteger(dias) || dias <= 0 || dias > 100) throw new Error('El plazo debe ser de 1 a 100 días hábiles');
    let actual = fechaUTC(fechaEmision);
    let restantes = dias;
    while (restantes > 0) {
      actual.setUTCDate(actual.getUTCDate() + 1); // El día de emisión no se cuenta.
      if (this.esDiaHabil(formatoISO(actual))) restantes -= 1;
    }
    return formatoISO(actual);
  }
}



class Factura {
  #datos;
  constructor(datos) {
    if (!datos || typeof datos !== 'object' || Array.isArray(datos)) throw new Error('Factura inexistente o incorrecta');
    if ((typeof datos.id !== 'number' && typeof datos.id !== 'string') || String(datos.id).trim() === '') {
      throw new Error('Factura sin ID');
    }
    if (!['pendiente', 'vencida', 'pagada', 'anulada'].includes(datos.estado)) {
      throw new Error(`Estado de factura inválido: ${String(datos.estado)}`);
    }
    if (typeof datos.cliente !== 'string' || !datos.cliente.trim()) throw new Error('Factura sin cliente');
    if (typeof datos.monto !== 'number' || !Number.isFinite(datos.monto) || datos.monto <= 0) {
      throw new Error('Monto de factura inválido');
    }
    fechaUTC(datos.fechaEmision);
    if (datos.fechaVencimiento != null) fechaUTC(datos.fechaVencimiento);
    this.#datos = { ...datos };
  }
  get id() { return this.#datos.id; }
  get estado() { return this.#datos.estado; }
  get fechaEmision() { return this.#datos.fechaEmision; }
  calcularVencimiento(calendario, diasHabiles = 15) {
    return calendario.sumarDiasHabiles(this.fechaEmision, diasHabiles);
  }
  estaVencida(hoy, vencimiento) {
    fechaUTC(hoy);
    fechaUTC(vencimiento);
    return hoy > vencimiento; // Vence al acabar la fecha indicada.
  }
  planificarActualizacion(calendario, hoy, diasHabiles = 15) {
    if (this.estado === 'pagada' || this.estado === 'anulada') {
      return { tipo: 'sin_cambios', id: this.id, motivo: `Factura ${this.estado}; se respeta su estado` };
    }
    const fechaVencimiento = this.calcularVencimiento(calendario, diasHabiles);
    const estado = this.estaVencida(hoy, fechaVencimiento) ? 'vencida' : 'pendiente';
    const actualizacion = { fechaVencimiento, estado };
    const cambio = this.#datos.fechaVencimiento !== fechaVencimiento || this.estado !== estado;
    return cambio
      ? { tipo: 'actualizar', id: this.id, cliente: this.#datos.cliente, actualizacion,
          motivo: estado === 'vencida' ? 'Plazo de pago superado' : 'Vencimiento calculado' }
      : { tipo: 'sin_cambios', id: this.id, motivo: 'Ya estaba actualizado' };
  }
}


