 throw new Error('API Nager.Date devolvió fechas del año siguiente fuera de rango');
}
const calendario = new CalendarioLaboral([...c.feriadosActuales, ...r.body], [c.anioActual,c.anioSiguiente]);
if (c.facturas.length === 0) return [{json:{tipo:'sin_cambios',motivo:'No hay facturas en JSON Server'}}];
return c.facturas.map(registro => {
 try {
